import SwiftUI

struct SWAYBeatsScreen: View {
    @StateObject private var model = SWAYBeatViewModel()
    var body: some View { SWAYScreen { VStack(alignment: .leading, spacing: 18) { Text("Beats").font(.largeTitle.bold()); Picker("Music source", selection: $model.source) { Text("SWAY Beats").tag("SWAY Beats"); Text("Your Music").tag("Your Music") }.pickerStyle(.segmented); ZStack(alignment: .bottomLeading) { LinearGradient(colors: [SWAYUI.violet, SWAYUI.pink.opacity(0.55)], startPoint: .topLeading, endPoint: .bottomTrailing); VStack(alignment: .leading) { Text("GOOD ENERGY").font(.largeTitle.bold()); Text("Bright pop • \(Int(model.tempo)) BPM").foregroundStyle(.white.opacity(0.75)) }.padding(22) }.frame(height: 220).clipShape(RoundedRectangle(cornerRadius: 28)); Text("Style").font(.title2.bold()); ScrollView(.horizontal, showsIndicators: false) { HStack { ForEach(["Pop", "Latin", "Hip Hop", "EDM", "Tropical"], id: \.self) { style in Button { model.style = style } label: { SWAYChip(title: style, selected: model.style == style) }.buttonStyle(.plain) } } }; slider("Tempo", value: $model.tempo, range: 70...150, detail: "\(Int(model.tempo)) BPM"); slider("Intensity", value: $model.intensity, range: 0...1, detail: "\(Int(model.intensity * 100))%"); Button("Generate New Beat") { model.generate() }.buttonStyle(SWAYPrimaryButtonStyle()).accessibilityHint("Creates a new offline beat variation") } }.toolbar(.hidden, for: .navigationBar) }
    private func slider(_ title: String, value: Binding<Double>, range: ClosedRange<Double>, detail: String) -> some View { VStack { HStack { Text(title).font(.headline); Spacer(); Text(detail).foregroundStyle(SWAYUI.secondary) }; Slider(value: value, in: range).tint(SWAYUI.pink) }.padding().background(SWAYUI.card, in: RoundedRectangle(cornerRadius: 18)) }
}

struct SWAYProgressScreen: View {
    @EnvironmentObject private var store: SwayStore
    @State private var section = "Overview"
    var body: some View { SWAYScreen { VStack(alignment: .leading, spacing: 18) { Text("Progress").font(.largeTitle.bold()); Picker("Progress section", selection: $section) { ForEach(["Overview", "Activity", "Achievements"], id: \.self) { Text($0) } }.pickerStyle(.segmented); HStack { SWAYStatTile(value: "\(store.sessionsCompleted)", label: "Workouts"); SWAYStatTile(value: "3", label: "Day Streak"); SWAYStatTile(value: "482", label: "Calories") }; SWAYCard { VStack(alignment: .leading, spacing: 14) { Text("Weekly Activity").font(.title3.bold()); HStack(alignment: .bottom, spacing: 14) { ForEach(Array([0.25, 0.7, 0.4, 0.9, 0.55, 0.1, 0.45].enumerated()), id: \.offset) { index, height in VStack { Capsule().fill(SWAYUI.pink).frame(width: 18, height: 100 * height); Text(["M", "T", "W", "T", "F", "S", "S"][index]).font(.caption2) }.frame(maxWidth: .infinity, alignment: .bottom) } }.frame(height: 125) } }; Text("Recent Workouts").font(.title2.bold()); recent("Foundation Flow", "Today • 15 min", "Completed", SWAYUI.neon); recent("Good Energy", "Tuesday • 7 min", "Ended Early", .orange) } } }
    private func recent(_ title: String, _ detail: String, _ status: String, _ color: Color) -> some View { HStack { VStack(alignment: .leading) { Text(title).font(.headline); Text(detail).font(.caption).foregroundStyle(SWAYUI.secondary) }; Spacer(); Text(status).font(.caption.bold()).foregroundStyle(color).padding(8).background(color.opacity(0.12), in: Capsule()) }.padding().background(SWAYUI.card, in: RoundedRectangle(cornerRadius: 18)) }
}

struct SWAYProfileScreen: View {
    @EnvironmentObject private var store: SwayStore
    @State private var creator = false
    var body: some View { SWAYScreen { VStack(alignment: .leading, spacing: 18) { Text("Profile").font(.largeTitle.bold()); SWAYCard { HStack { SWAYCharacterStage(character: .yourDancer, source: .idle, profile: store.character).frame(width: 130, height: 180); VStack(alignment: .leading) { Text("YOUR DANCER").font(.title2.bold()); Text("Make every move yours").foregroundStyle(SWAYUI.secondary); Button("Create / Edit") { creator = true }.buttonStyle(.borderedProminent).tint(SWAYUI.pink) } } }; NavigationLink { SWAYCoachChoiceScreen() } label: { row("Coach", "Lucia", "person.2.fill") }; NavigationLink { SWAYProgressScreen() } label: { row("Progress", "Activity and achievements", "chart.bar.fill") }; NavigationLink { SWAYSettingsScreen() } label: { row("Health, Music & Permissions", "Manage connections and privacy", "checkmark.shield.fill") }; NavigationLink { SWAYRecordPreviewScreen() } label: { row("Record SWAY", "Preview, save and share", "record.circle") } }.sheet(isPresented: $creator) { SWAYAvatarCreatorScreen().environmentObject(store) } }.toolbar(.hidden, for: .navigationBar) }
    private func row(_ title: String, _ detail: String, _ icon: String) -> some View { HStack { Image(systemName: icon).frame(width: 44).foregroundStyle(SWAYUI.pink); VStack(alignment: .leading) { Text(title).font(.headline); Text(detail).font(.caption).foregroundStyle(SWAYUI.secondary) }; Spacer(); Image(systemName: "chevron.right") }.padding().background(SWAYUI.card, in: RoundedRectangle(cornerRadius: 18)) }
}

struct SWAYCoachChoiceScreen: View {
    @EnvironmentObject private var store: SwayStore
    var body: some View { SWAYScreen { VStack(alignment: .leading, spacing: 18) { Text("Choose Your Coach").font(.largeTitle.bold()); ForEach(SWAYCharacterID.allCases.filter { $0 != .yourDancer }, id: \.rawValue) { coach in Button { store.coachProfileID = coach.rawValue; store.save() } label: { HStack { SWAYCharacterStage(character: coach, source: .idle).frame(width: 90, height: 120); Text(coach.displayName).font(.title3.bold()); Spacer(); if store.coachProfileID == coach.rawValue { Image(systemName: "checkmark.circle.fill").foregroundStyle(SWAYUI.pink) } }.padding().background(SWAYUI.card, in: RoundedRectangle(cornerRadius: 20)) }.buttonStyle(.plain) } } } }
}
